body.script:
(function () {
  var button = document.getElementById('open');
  var status = document.getElementById('status');
  var timer;
  function show(text) { status.textContent = text; status.hidden = false; }
  // Derive fallback from this deployment, never from a caller-controlled redirect parameter.
  var fallback = new URL(location.href);
  fallback.search = '?v=fb';
  fallback.hash = '';
  button.href = 'intent://open#Intent;scheme=com.apporo.assistant;package=com.apporo.assistant;S.browser_fallback_url=' + encodeURIComponent(fallback.href) + ';end';
  if (!/Android/i.test(navigator.userAgent)) {
    button.hidden = true;
    show('Open this page on an Android phone with Apporo Assistant installed.');
    return;
  }
  if (new URLSearchParams(location.search).get('v') === 'fb') {
    show('The browser could not open the app. Install Apporo .7 or later, or try opening this page in Chrome.');
  }
  button.addEventListener('click', function () {
    clearTimeout(timer);
    status.hidden = true;
    timer = setTimeout(function () {
      if (!document.hidden) show('If the app did not open, check the installed version or try Chrome from the LINE menu.');
    }, 2500);
  });
  document.addEventListener('visibilitychange', function () {
    if (document.hidden) clearTimeout(timer);
  });
})();
